-- Restore Luclin-and-earlier spawnpoints recorded at seven days or less in
-- the 2025-05-08 Git database dump. Cap the other affected points at seven days.
-- PoP spawnpoints are outside this change.
UPDATE spawn2
SET respawntime = CASE id
    WHEN 325426 THEN 259200
    WHEN 325509 THEN 583200
    WHEN 325540 THEN 259200
    WHEN 334628 THEN 259200
    WHEN 334681 THEN 561600
    WHEN 334739 THEN 18000
    WHEN 338425 THEN 453600
    WHEN 352796 THEN 561600
    WHEN 352798 THEN 561600
    WHEN 352881 THEN 1200
    WHEN 352884 THEN 1200
    WHEN 352892 THEN 1200
    WHEN 352893 THEN 1200
    WHEN 354962 THEN 259200
    WHEN 357118 THEN 216000
    WHEN 357119 THEN 216000
    WHEN 369111 THEN 561600
    WHEN 369137 THEN 561600
    WHEN 369138 THEN 561600
    WHEN 369139 THEN 561600
    WHEN 369140 THEN 561600
    ELSE 604800
END,
variance = CASE id
    WHEN 325426 THEN 86400
    WHEN 325509 THEN 43200
    WHEN 325540 THEN 86400
    WHEN 334681 THEN 86400
    WHEN 338425 THEN 43200
    WHEN 352796 THEN 86400
    WHEN 352798 THEN 86400
    WHEN 357118 THEN 86400
    WHEN 357119 THEN 86400
    WHEN 369111 THEN 86400
    WHEN 369137 THEN 86400
    WHEN 369138 THEN 86400
    WHEN 369139 THEN 86400
    WHEN 369140 THEN 86400
    ELSE 0
END
WHERE id IN (
    325426, 325509, 325540, 327387, 327388, 327389, 334628, 334681, 334739,
    336724, 337836, 337879, 338037, 338425, 338827, 341836, 344582, 351181,
    351655, 351663, 351685, 351686, 352796, 352798, 352881, 352884, 352892,
    352893, 354479, 354480, 354481, 354482, 354483, 354485, 354486, 354487,
    354488, 354489, 354490, 354519, 354648, 354962, 357118, 357119, 357515,
    357755, 363632, 364318, 364319, 364359, 364392, 364394, 364396, 364404,
    364559, 364564, 364568, 364569, 364598, 364623, 364631, 364639, 364645,
    364659, 364965, 364982, 364987, 365014, 365015, 365016, 365017, 365159,
    367983, 368005, 368030, 368069, 368238, 368250, 368256, 368281, 368294,
    368359, 368362, 368488, 368489, 368490, 368491, 369111, 369137, 369138,
    369139, 369140, 11448686, 11450600, 11450601, 11450602, 11450603, 11450604, 11450605,
    21450269
)
  AND respawntime = 1700000;

-- Keep elapsed time when repairing existing open-world countdowns.
UPDATE respawn_times AS rt
JOIN spawn2 AS s ON s.id = rt.id
SET rt.duration = s.respawntime
WHERE rt.guild_id = 4294967295
  AND rt.duration = 1700000
  AND s.id IN (
    325426, 325509, 325540, 327387, 327388, 327389, 334628, 334681, 334739,
    336724, 337836, 337879, 338037, 338425, 338827, 341836, 344582, 351181,
    351655, 351663, 351685, 351686, 352796, 352798, 352881, 352884, 352892,
    352893, 354479, 354480, 354481, 354482, 354483, 354485, 354486, 354487,
    354488, 354489, 354490, 354519, 354648, 354962, 357118, 357119, 357515,
    357755, 363632, 364318, 364319, 364359, 364392, 364394, 364396, 364404,
    364559, 364564, 364568, 364569, 364598, 364623, 364631, 364639, 364645,
    364659, 364965, 364982, 364987, 365014, 365015, 365016, 365017, 365159,
    367983, 368005, 368030, 368069, 368238, 368250, 368256, 368281, 368294,
    368359, 368362, 368488, 368489, 368490, 368491, 369111, 369137, 369138,
    369139, 369140, 11448686, 11450600, 11450601, 11450602, 11450603, 11450604, 11450605,
    21450269
);

-- Repair already-running Guild 2+ countdowns. Prefer the valid NPC
-- instance override, including older spawn groups with multiple NPC versions.
-- Chardok's 1,592,000,000-ms override is a sentinel, not a respawn.
UPDATE respawn_times AS rt
JOIN spawn2 AS s ON s.id = rt.id
LEFT JOIN (
    SELECT se.spawngroupID,
           MAX(CASE
               WHEN n.instance_spawn_timer_override BETWEEN 1 AND 604800000
               THEN n.instance_spawn_timer_override
               ELSE 0
           END) AS valid_override
    FROM spawnentry AS se
    JOIN npc_types AS n ON n.id = se.npcID
    GROUP BY se.spawngroupID
) AS o ON o.spawngroupID = s.spawngroupID
SET rt.duration = CASE
    WHEN o.valid_override > 0
    THEN FLOOR(o.valid_override / 1000)
    ELSE LEAST(GREATEST(s.respawntime, 64800), 604800)
END
WHERE rt.guild_id BETWEEN 2 AND 4294967294
  AND rt.duration > 604800
  AND (s.id IN (
    325426, 325509, 325540, 327387, 327388, 327389, 334628, 334681, 334739,
    336724, 337836, 337879, 338037, 338425, 338827, 341836, 344582, 351181,
    351655, 351663, 351685, 351686, 352796, 352798, 352881, 352884, 352892,
    352893, 354479, 354480, 354481, 354482, 354483, 354485, 354486, 354487,
    354488, 354489, 354490, 354519, 354648, 354962, 357118, 357119, 357515,
    357755, 363632, 364318, 364319, 364359, 364392, 364394, 364396, 364404,
    364559, 364564, 364568, 364569, 364598, 364623, 364631, 364639, 364645,
    364659, 364965, 364982, 364987, 365014, 365015, 365016, 365017, 365159,
    367983, 368005, 368030, 368069, 368238, 368250, 368256, 368281, 368294,
    368359, 368362, 368488, 368489, 368490, 368491, 369111, 369137, 369138,
    369139, 369140, 11448686, 11450600, 11450601, 11450602, 11450603, 11450604, 11450605,
    21450269
) OR s.zone IN ('chardok', 'chardok_instanced'));
